t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read()

# Extract demo pair 1
demopair1 = {}
in_demopair1 = False
for line in t.split('\n'):
    if 'Demo pair 1 input' in line:
        in_demopair1 = True
        continue
    if in_demopair1:
        if not line.strip():
            break
        demopair1['input'] = line.strip()
        continue
    if 'Demo pair 1 output' in line and line.strip() == 'Demo pair 1 output (13x13):':
        in_demopair1 = False
        continue
    if not in_demopair1 and not line.strip():
        continue

print(demopair1)

# Generate final output
rows = 30
cols = 30
grid = [[0] * cols for _ in range(rows)]

for i in range(1, 27):
    for j in range(1, 26):
        if i == 1 or i == 26 or j == 1 or j == 25:
            grid[i][j] = 5

def transform(input_grid):
    rows = len(input_grid)
    cols = len(input_grid[0])

    r_min, r_max, c_min, c_max = rows, 0, cols, 0
    for i in range(rows):
        for j in range(cols):
            if input_grid[i][j] == 5:
                r_min = min(r_min, i)
                r_max = max(r_max, i)
                c_min = min(c_min, j)
                c_max = max(c_max, j)

    result = [row[:] for row in input_grid]

    for i in range(r_min + 1, r_max):
        for j in range(c_min + 1, c_max):
            dist = min(i - r_min, r_max - i, j - c_min, c_max - j)
            if dist == 1:
                result[i][j] = 2
            elif dist == 2:
                result[i][j] = 5
            else:
                result[i][j] = 0

    return result

